std::priority_queue<std::pair<double, TreeNode*>,
                    std::vector<std::pair<double, TreeNode*>>,
                    std::greater<std::pair<double, TreeNode*>>> pq;

for (int i = 0; i < size; ++i) {
    TreeNode* node = new TreeNode{values[i], freqs[i], nullptr, nullptr};
    pq.push({freqs[i], node});
}

while (pq.size() > 1) {
    auto left = pq.top(); pq.pop();
    auto right = pq.top(); pq.pop();

    double sumFreq = left.first + right.first;
    TreeNode* internalNode = new TreeNode{0, sumFreq, left.second, right.second};
    pq.push({sumFreq, internalNode});
}

TreeNode* root = pq.empty() ? nullptr : pq.top().second;
return root;
// END_CODE

